// 1D DP：dp[j] = 走到當前列第 j 格的最小路徑和
// 時間複雜度: O(m·n)，空間複雜度: O(n)
function minPathSum(grid) {
    const n = grid[0].length;
    const dp = new Array(n).fill(Infinity);
    dp[0] = 0;
    for (const row of grid) {
        dp[0] += row[0];
        for (let j = 1; j < n; j++) {
            dp[j] = Math.min(dp[j], dp[j - 1]) + row[j]; // 從上方或左方來
        }
    }
    return dp[n - 1];
}

