// 1D DP：dp[j] = 走到當前列第 j 格的最小路徑和
// 時間複雜度: O(m·n)，空間複雜度: O(n)
int minPathSum(int** grid, int gridSize, int* gridColSize) {
    int n = gridColSize[0];
    int* dp = malloc(sizeof(int) * n);
    dp[0] = grid[0][0];
    for (int j = 1; j < n; j++) dp[j] = dp[j - 1] + grid[0][j];   // 第一列只能從左來

    for (int i = 1; i < gridSize; i++) {
        dp[0] += grid[i][0];
        for (int j = 1; j < n; j++) {
            dp[j] = (dp[j] < dp[j - 1] ? dp[j] : dp[j - 1]) + grid[i][j];
        }
    }
    int ans = dp[n - 1];
    free(dp);
    return ans;
}

